'use strict';
const speakingPractice={subject:'all',lessonId:null,wordId:null,config:null,configLoading:false,error:'',busy:false,recording:false,seconds:0,recorder:null,stream:null,timer:null,chunks:[],blob:null,url:null,base64:'',requestId:null,result:null,generation:0,cancelled:false,devices:[],deviceId:'',inputName:'',level:0,checking:false};
function speakingWords(){if(speakingPractice.subject!=='all'&&!gradeSubjects().some(s=>s.id===speakingPractice.subject))speakingPractice.subject='all';if(speakingPractice.lessonId){const lesson=lessonById(speakingPractice.lessonId);if(lesson?.grade===state.grade)return lessonWords(lesson.id);speakingPractice.lessonId=null;}return gradeWords().filter(w=>speakingPractice.subject==='all'||w.subject===speakingPractice.subject);}
function speakingWord(){const list=speakingWords();let word=list.find(w=>w.id===speakingPractice.wordId)||list[0];if(word)speakingPractice.wordId=word.id;return word;}
function speakingRefresh(){if(view==='speaking'&&!currentModal)$('#main-content').innerHTML=renderSpeaking();}
async function ensureSpeakingConfig(){if(speakingPractice.config||speakingPractice.configLoading||speakingPractice.configAttempted)return;speakingPractice.configLoading=true;speakingPractice.configAttempted=true;try{const r=await fetch('/api/speaking/config',{credentials:'same-origin'});if(!r.ok)throw new Error('Speaking is unavailable. / Luyện nói chưa sẵn sàng.');speakingPractice.config=await r.json();}catch(e){speakingPractice.error=e.message;}finally{speakingPractice.configLoading=false;speakingRefresh();}}
function clearSpeakingRecording(){speakingPractice.generation++;cancelSpeakingRecording();if(speakingPractice.url)URL.revokeObjectURL(speakingPractice.url);Object.assign(speakingPractice,{blob:null,url:null,base64:'',requestId:null,result:null,error:'',busy:false,checking:false});}
function cancelSpeakingRecording(){speakingPractice.cancelled=true;clearInterval(speakingPractice.timer);speakingPractice.recorder?.cancel?.();for(const track of speakingPractice.stream?.getTracks()||[])track.stop();speakingPractice.recording=false;speakingPractice.stream=null;speakingPractice.level=0;audioSessionPlayback();}
function openSpeakingLesson(id){clearSpeakingRecording();const lesson=lessonById(id);if(!lesson)return;state.grade=lesson.grade;speakingPractice.lessonId=id;speakingPractice.subject=lesson.subject;speakingPractice.wordId=lesson.wordIds[0];navigate('speaking');}
function speakingTrackingNotice(){const student=typeof classroom!=='undefined'&&classroom.student;return student?`<p class="speaking-share">Shared with ${esc(student.className)} · ${esc(student.name)}</p>`:'<button class="text-link speaking-share" data-action="nav" data-view="classroom">Join class to share results</button>';}
function renderSpeaking(){
  ensureSpeakingConfig();const word=speakingWord(),list=speakingWords();if(!word)return `${pageHeading()}<p>No words.</p>`;
  const p=speakingPractice,result=p.result,busy=p.busy||p.recording;
  return `${pageHeading('','','',true)}<div class="speaking-layout ${result?'':'speaking-solo'}"><section class="speaking-card"><div class="speaking-pickers"><label class="form-field">Subject<select data-speaking-subject ${busy?'disabled':''}><option value="all">All subjects</option>${gradeSubjects().map(s=>`<option value="${s.id}" ${p.subject===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="form-field">Word<select data-speaking-word ${busy?'disabled':''}>${list.map(w=>`<option value="${w.id}" ${w.id===word.id?'selected':''}>${esc(w.en)} / ${esc(w.vi)}</option>`).join('')}</select></label></div><div class="speaking-target"><h2 lang="en">${esc(word.en)}</h2><p lang="vi">${esc(word.vi)}</p>${IPA[word.en]?`<div class="speaking-ipa">${esc(IPA[word.en])}</div>`:''}</div><div class="speaking-reference"><button class="btn secondary" data-action="speaking-listen" ${p.recording?'disabled':''}>${icon('sound')}Listen</button><audio hidden controls preload="none" playsinline aria-label="Model pronunciation"></audio><p class="audio-status" role="status"></p></div>${p.error?`<p class="speaking-error" role="alert">${esc(p.error)}</p>`:''}${p.recording?`<div class="speaking-mic-monitor"><span>${esc(p.inputName)}</span><meter id="speaking-mic-level" min="0" max="100" value="0" aria-label="Mic level"></meter><span id="speaking-mic-status" role="status">Speak now</span></div>`:''}${speakingCaptureControls()}${p.url?`<div class="speaking-recording"><strong>Your recording</strong><audio controls preload="metadata" playsinline src="${p.url}" aria-label="Your recording"></audio></div>`:''}<p class="speaking-privacy">Check sends audio to OpenAI.<br><span lang="vi">Bấm Check sẽ gửi bản ghi đến OpenAI.</span></p>${speakingTrackingNotice()}${p.config&&!p.config.enabled?'<p class="speaking-error">AI feedback is offline.</p>':''}<details class="speaking-options"><summary>Options</summary><label class="form-field speaking-microphone">Microphone<select data-speaking-microphone ${busy?'disabled':''}><option value="">Default</option>${p.devices.map(d=>`<option value="${esc(d.deviceId)}" ${p.deviceId===d.deviceId?'selected':''}>${esc(d.label||'Microphone')}</option>`).join('')}</select></label><label class="speaking-upload">Upload audio<input type="file" accept="audio/*" data-speaking-file ${busy?'disabled':''}></label><a class="speaking-open-audio" href="${pronunciationURL(word,true)}" target="_blank" rel="noopener">Open audio ↗</a></details></section>${result?`<aside id="speaking-outcome" class="speaking-result has-result" aria-live="polite" aria-atomic="true">${speakingFeedbackHTML(result)}<small class="speaking-feedback-note">AI practice feedback</small></aside>`:''}</div>${footer()}`;
}
function speakingCaptureControls(){
  const p=speakingPractice;
  return '<div class="speaking-capture-actions"><div class="speaking-record-action"><button class="btn '+(p.recording?'recording':'primary')+'" data-action="speaking-record" '+(p.busy?'disabled':'')+'>'+icon(p.recording?'stop':'mic')+(p.recording?'Stop':'Record')+'</button><span id="speaking-timer" role="status">'+(p.recording?p.seconds+'s / 10s':'10s max')+'</span></div>'+speakingCheckControl()+'</div>';
}
function speakingCheckControl(){const p=speakingPractice,disabled=p.busy||p.recording||!p.base64||!p.config?.enabled||!!p.result,label=p.checking?'Checking…':p.busy?'Preparing…':'Check',hint=p.recording?'Recording…':p.checking?'Checking…':p.busy?'Preparing…':p.result?'':p.base64?'Ready':'Record first';return '<div class="speaking-check-control"><button class="btn primary full-width" data-action="speaking-check" '+(disabled?'disabled':'')+'>'+icon('checkcircle')+label+'</button>'+(hint?'<p class="speaking-check-hint" role="status">'+hint+'</p>':'')+'</div>';}
function speakingFeedbackHTML(r){
  const verdict=['clear','nearly','practice','unclear'].includes(r.verdict)?r.verdict:'unclear',passed=verdict==='clear',labels={clear:['Correct!','Đúng rồi!'],nearly:['Almost!','Gần đúng'],practice:['Try again','Chưa đúng'],unclear:['Not clear','Chưa nghe rõ']},label=labels[verdict],list=speakingWords(),last=list.findIndex(w=>w.id===speakingPractice.wordId)===list.length-1;
  return '<div class="speaking-result-summary '+verdict+'"><span class="speaking-result-symbol">'+icon(passed?'checkcircle':'mic')+'</span><h2 class="speaking-verdict '+verdict+'">'+label[0]+'<small lang="vi">'+label[1]+'</small></h2></div><div class="speaking-result-actions">'+(passed?'<button class="btn primary" data-action="speaking-next">'+(last?'Start again':'Next word')+icon('arrow')+'</button>':'<button class="btn primary" data-action="speaking-retry">'+icon('mic')+'Speak again</button>')+'<button class="btn secondary" data-action="speaking-listen">'+icon('sound')+'Listen</button></div>'+(r.tip_en?'<div class="speaking-tip"><p lang="en">'+esc(r.tip_en)+'</p><p lang="vi">'+esc(r.tip_vi)+'</p></div>':'')+'<details class="speaking-feedback-details"><summary>Feedback</summary>'+(r.heard?'<div class="speaking-heard"><span>Heard</span><strong lang="en">'+esc(r.heard)+'</strong></div>':'')+'<p lang="en">'+esc(r.feedback_en)+'</p><p lang="vi">'+esc(r.feedback_vi)+'</p></details>';
}
function retrySpeaking(){if(speakingPractice.busy||speakingPractice.recording||!speakingPractice.result||speakingPractice.result.verdict==='clear')return;startSpeakingRecording();}
function nextSpeakingWord(){
  const p=speakingPractice;if(p.busy||p.recording||p.result?.verdict!=='clear')return;
  const words=speakingWords(),index=words.findIndex(w=>w.id===p.wordId);if(!words.length)return;clearSpeakingRecording();p.wordId=words[(index+1)%words.length].id;window.LexiAudio.stop();speakingRefresh();document.querySelector('.speaking-target')?.scrollIntoView({behavior:'smooth',block:'center'});
}
function speakingWav(buffer){
  const channels=buffer.numberOfChannels,length=buffer.length,rate=buffer.sampleRate,data=new Float32Array(length);for(let c=0;c<channels;c++){const a=buffer.getChannelData(c);for(let i=0;i<length;i++)data[i]+=a[i]/channels;}
  const output=new ArrayBuffer(44+length*2),v=new DataView(output),str=(at,s)=>{for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i));};str(0,'RIFF');v.setUint32(4,36+length*2,true);str(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*2,true);let power=0,peak=0;for(let i=0;i<length;i++){const x=Math.max(-1,Math.min(1,data[i]));power+=x*x;peak=Math.max(peak,Math.abs(x));v.setInt16(44+i*2,Math.round(x*(x<0?32768:32767)),true);}return {bytes:new Uint8Array(output),rms:Math.sqrt(power/length),peak};
}
// Keep speech and trim long waiting periods before normalising a quiet microphone.
function prepareVoicePCM(buffer){
  const rate=buffer.sampleRate;if(!buffer.length||buffer.duration<.25||buffer.duration>12)throw new Error('Record for 1–10 seconds. / Hãy ghi âm khoảng 1–10 giây.');
  let data=null,best=-1;for(let c=0;c<buffer.numberOfChannels;c++){const ch=buffer.getChannelData(c);let power=0;for(const x of ch)power+=x*x;if(power>best){best=power;data=ch;}}
  const frame=Math.max(1,Math.round(rate*.02)),levels=[];let peak=0,maxLevel=0;
  for(let at=0;at<data.length;at+=frame){let power=0;const count=Math.min(frame,data.length-at);for(let i=0;i<count;i++){const x=data[at+i];power+=x*x;peak=Math.max(peak,Math.abs(x));}const level=Math.sqrt(power/count);levels.push(level);maxLevel=Math.max(maxLevel,level);}
  if(maxLevel<.00008||peak<.0003)throw new Error('No microphone signal. Select the correct microphone and try again. / Chưa nhận được tín hiệu mic. Hãy chọn đúng mic rồi ghi lại.');
  const gate=Math.max(.00008,maxLevel*.07);let first=levels.findIndex(x=>x>=gate),last=levels.length-1;while(last>first&&levels[last]<gate)last--;
  const from=Math.max(0,first*frame-Math.round(rate*.15)),to=Math.min(data.length,(last+1)*frame+Math.round(rate*.25));
  const gain=Math.min(20,.08/maxLevel,.9/peak),size=Math.max(4000,Math.ceil((to-from)*16000/rate)),samples=new Float32Array(size);
  for(let i=0;i<size;i++){const pos=from+i*rate/16000,left=Math.floor(pos);if(left>=to)break;const frac=pos-left;samples[i]=Math.max(-1,Math.min(1,((data[left]||0)*(1-frac)+(data[Math.min(left+1,to-1)]||0)*frac)*gain));}
  return {numberOfChannels:1,length:size,sampleRate:16000,duration:size/16000,getChannelData:()=>samples};
}
async function prepareSpeakingBuffer(buffer,generation){
  if(generation!==speakingPractice.generation)return;speakingPractice.busy=true;speakingPractice.error='';speakingRefresh();
  try{
    const wav=speakingWav(prepareVoicePCM(buffer));
    if(wav.rms<.003||wav.peak<.015)throw new Error('The microphone signal is still very low. Select another microphone or raise its input volume. / Tín hiệu mic vẫn quá nhỏ. Hãy chọn mic khác hoặc tăng âm lượng đầu vào.');
    if(generation!==speakingPractice.generation)return;if(speakingPractice.url)URL.revokeObjectURL(speakingPractice.url);
    speakingPractice.blob=new Blob([wav.bytes],{type:'audio/wav'});speakingPractice.url=URL.createObjectURL(speakingPractice.blob);
    let raw='';for(let i=0;i<wav.bytes.length;i+=8192)raw+=String.fromCharCode(...wav.bytes.subarray(i,i+8192));speakingPractice.base64=btoa(raw);speakingPractice.requestId=crypto.randomUUID();speakingPractice.result=null;
  }catch(e){if(generation===speakingPractice.generation)speakingPractice.error=e.message||'Recording could not be read. / Chưa đọc được bản ghi.';}finally{if(generation===speakingPractice.generation){speakingPractice.busy=false;speakingRefresh();}}
}
async function prepareSpeakingRecording(blob,generation){
  speakingPractice.busy=true;speakingPractice.error='';speakingRefresh();
  try{const context=unlockWordAudio();if(!context)throw new Error('Open LeVo in Safari or Chrome. / Hãy mở LeVo bằng Safari hoặc Chrome.');const decoded=await context.decodeAudioData(await blob.arrayBuffer());await prepareSpeakingBuffer(decoded,generation);}
  catch(e){if(generation===speakingPractice.generation){speakingPractice.busy=false;speakingPractice.error=e.message||'This audio file could not be read. / Chưa đọc được file âm thanh.';speakingRefresh();}}
}
function speakingMicLevel(level){
  const p=speakingPractice;if(!p.recording)return;p.level=level;const meter=document.getElementById('speaking-mic-level');if(meter)meter.value=Math.min(100,Math.round(Math.sqrt(level)*250));
  const label=document.getElementById('speaking-mic-status');if(label)label.textContent=level>.001?'Voice detected':'Speak now';
}
async function finishSpeakingRecording(){
  const p=speakingPractice;if(!p.recording)return;const generation=p.generation,recorder=p.recorder,stream=p.stream;clearInterval(p.timer);p.recording=false;p.busy=true;speakingRefresh();
  try{const buffer=await recorder.stop();for(const track of stream?.getTracks()||[])track.stop();audioSessionPlayback();if(generation!==p.generation)return;p.stream=null;await prepareSpeakingBuffer(buffer,generation);}
  catch{for(const track of stream?.getTracks()||[])track.stop();audioSessionPlayback();if(generation===p.generation){p.busy=false;p.error='Recording was interrupted. Try again. / Ghi âm bị gián đoạn. Hãy thử lại.';speakingRefresh();}}
}
async function startSpeakingRecording(){
  if(speakingPractice.recording){finishSpeakingRecording();return;}
  if(!navigator.mediaDevices?.getUserMedia){speakingPractice.error='Microphone access is unavailable. Open the HTTPS link in Safari or Chrome. / Chưa truy cập được mic. Hãy mở link HTTPS bằng Safari hoặc Chrome.';speakingRefresh();return;}
  clearSpeakingRecording();window.LexiAudio.stop();const context=unlockWordAudio(),generation=speakingPractice.generation;speakingPractice.busy=true;speakingRefresh();let stream;
  try{
    if(!context)throw new Error('Audio context unavailable');try{if(navigator.audioSession)navigator.audioSession.type='auto';}catch{}
    stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:{ideal:1},...(speakingPractice.deviceId?{deviceId:{exact:speakingPractice.deviceId}}:{})},video:false});
    if(generation!==speakingPractice.generation){stream.getTracks().forEach(t=>t.stop());audioSessionPlayback();return;}
    speakingPractice.stream=stream;const track=stream.getAudioTracks()[0];speakingPractice.inputName=track?.label||'Microphone / Micrô';
    try{speakingPractice.devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='audioinput');}catch{}
    const recorder=await createVoiceRecorder(stream,context,speakingMicLevel);if(generation!==speakingPractice.generation){recorder.cancel();stream.getTracks().forEach(t=>t.stop());audioSessionPlayback();return;}
    Object.assign(speakingPractice,{recorder,recording:true,busy:false,seconds:0,cancelled:false,level:0});
    if(track)track.onended=()=>{if(speakingPractice.recording)finishSpeakingRecording();};
    speakingPractice.timer=setInterval(()=>{speakingPractice.seconds++;const timer=document.getElementById('speaking-timer');if(timer)timer.textContent=speakingPractice.seconds+'s / 10s';if(speakingPractice.seconds>=10)finishSpeakingRecording();},1000);speakingRefresh();
  }catch(e){for(const track of stream?.getTracks()||[])track.stop();audioSessionPlayback();if(generation!==speakingPractice.generation)return;speakingPractice.stream=null;speakingPractice.busy=false;speakingPractice.error=e.name==='NotAllowedError'?'Allow microphone access for LeVo in the browser and system settings. / Cho phép LeVo dùng mic trong cài đặt trình duyệt và hệ thống.':e.name==='NotFoundError'||e.name==='OverconstrainedError'?'The selected microphone is unavailable. Select another microphone. / Mic đã chọn chưa khả dụng. Hãy chọn mic khác.':'Could not start the microphone. Select another input or choose an audio file. / Chưa mở được mic. Chọn mic khác hoặc chọn file ghi âm.';speakingRefresh();}
}
async function checkSpeaking(){
  const p=speakingPractice,word=speakingWord();if(p.busy||p.recording||p.result||!p.base64||!word)return;window.LexiAudio.stop();p.busy=true;p.checking=true;p.error='';p.result=null;speakingRefresh();const generation=p.generation,controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);
  try{const token=typeof classroom!=='undefined'?classroom.token:'';const response=await fetch('/api/speaking/check',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})},body:JSON.stringify({requestId:p.requestId,wordId:word.id,lessonId:p.lessonId,audio:p.base64}),signal:controller.signal});const result=await response.json();if(!response.ok){if(response.status===503)p.requestId=crypto.randomUUID();throw new Error(result.error||'Please try again. / Hãy thử lại.');}if(!['clear','nearly','practice','unclear'].includes(result.verdict))throw new Error('The recording could not be checked. Please try again. / Chưa kiểm tra được bản ghi. Hãy thử lại.');if(generation!==p.generation)return;p.result=result;try{const history=JSON.parse(localStorage.getItem('lexilab-speaking-v1')||'[]');history.unshift({wordId:word.id,at:Date.now(),verdict:result.verdict,heard:result.heard});localStorage.setItem('lexilab-speaking-v1',JSON.stringify(history.slice(0,200)));}catch{}}
  catch(e){if(generation===p.generation){p.error=e.name==='AbortError'?'The check took too long. Try again shortly. / Kiểm tra lâu hơn dự kiến. Hãy thử lại sau một chút.':e.message;}}
  finally{clearTimeout(timeout);if(generation===p.generation){p.busy=false;p.checking=false;speakingRefresh();if(p.result)document.getElementById('speaking-outcome')?.scrollIntoView({behavior:'smooth',block:'center'});else if(p.error)document.querySelector('.speaking-error')?.scrollIntoView({behavior:'smooth',block:'center'});}}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='lesson-speaking')openSpeakingLesson(b.dataset.lesson);if(action==='speaking-record')startSpeakingRecording();if(action==='speaking-check')checkSpeaking();if(action==='speaking-retry')retrySpeaking();if(action==='speaking-next')nextSpeakingWord();if(action==='speaking-listen'){const w=speakingWord();window.LexiAudio.play(w,document.querySelector('.speaking-reference audio'));}});
document.addEventListener('change',e=>{if(e.target.matches('[data-speaking-microphone]')){clearSpeakingRecording();speakingPractice.deviceId=e.target.value;speakingRefresh();}if(e.target.matches('[data-speaking-subject]')){clearSpeakingRecording();speakingPractice.subject=e.target.value;speakingPractice.lessonId=null;speakingPractice.wordId=null;speakingRefresh();}if(e.target.matches('[data-speaking-word]')){clearSpeakingRecording();speakingPractice.wordId=e.target.value;speakingRefresh();}if(e.target.matches('[data-speaking-file]')&&e.target.files[0]){const file=e.target.files[0];clearSpeakingRecording();if(file.size>10000000){speakingPractice.error='Choose a short audio file. / Hãy chọn bản ghi ngắn.';speakingRefresh();return;}prepareSpeakingRecording(file,speakingPractice.generation);}});
window.addEventListener('pagehide',cancelSpeakingRecording);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&speakingPractice.recording)finishSpeakingRecording();});
